import{_ as t,a as o,b as a,c as r,d as s,e as n,f as i,g as p,h as l,i as c,j as g}from"./chunks/notifications.BgueT9nY.js";import{_ as d,o as h,c as m,a2 as u}from"./chunks/framework.Bzj1XTnB.js";const q=JSON.parse('{"title":"Getting started","description":"Your first project in Toonik — the home screen, creating a project, and keeping your work safe.","frontmatter":{"lang":"en","slug":"getting-started","order":1,"title":"Getting started","description":"Your first project in Toonik — the home screen, creating a project, and keeping your work safe."},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),w={name:"getting-started.md"};function f(k,e,y,b,_,T){return h(),m("div",null,[...e[0]||(e[0]=[u('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Toonik is a frame-by-frame animation app. You draw a picture, add a new frame, draw it again a little differently, and when the frames play one after another your drawing moves. Everything in the app is free, there is no account to create and no ads.</p><h2 id="the-home-screen" tabindex="-1">The home screen <a class="header-anchor" href="#the-home-screen" aria-label="Permalink to &quot;The home screen&quot;">​</a></h2><p><img src="'+t+'" alt="The home screen with four projects"></p><ul><li><strong>Projects</strong> and <strong>Movies</strong> — the two tabs. Swipe left or right to switch.</li><li><strong>☰ (menu)</strong> — opens the side menu (see below). A pink dot means there is something new to read.</li><li><strong>🔔 (bell)</strong> — your notifications from Toonik. A number shows how many are unread.</li><li><strong>Pink circle (top right)</strong> — opens Settings.</li><li><strong>Bottom bar</strong> — <strong>Home</strong>, <strong>Objects</strong> (the object library), <strong>+</strong> (new project), <strong>Learn</strong> (short animation lessons) and <strong>Settings</strong>.</li></ul><p>Tap a project to open it. The small labels on each card show how long the animation is and its frames per second (fps).</p><h3 id="the-side-menu" tabindex="-1">The side menu <a class="header-anchor" href="#the-side-menu" aria-label="Permalink to &quot;The side menu&quot;">​</a></h3><p><img src="'+o+'" alt="The side menu"></p><p><strong>App settings</strong>, <strong>Object library</strong>, <strong>How to animate</strong> (lessons), <strong>What&#39;s new</strong> (what each update brought), <strong>Notifications</strong>, <strong>About</strong>, <strong>Rate this app</strong> and <strong>Share Toonik</strong>.</p><h2 id="create-a-project" tabindex="-1">Create a project <a class="header-anchor" href="#create-a-project" aria-label="Permalink to &quot;Create a project&quot;">​</a></h2><p>Tap the pink <strong>+</strong> at the bottom.</p><p><img src="'+a+'" alt="New project screen"></p><ol><li><p><strong>Project name</strong> — type a name, or keep &quot;My Animation 1&quot;.</p></li><li><p><strong>Choose background</strong> — the four buttons under the preview:</p><ul><li><strong>Presets</strong> — paper, white, grid, lined, dot grid, sky, sunset, night sky, meadow, green screen, black and more.</li><li><strong>Camera</strong> — take a photo and draw over it.</li><li><strong>Gallery</strong> — use a picture from your phone.</li><li><strong>Color</strong> — a plain colour (pick a swatch or type a HEX code).</li></ul><p><img src="'+r+'" alt="Background presets"></p></li><li><p><strong>Choose canvas size</strong> — ready-made sizes for YouTube, YouTube Shorts, Instagram, TikTok, stickers and more, or type your own width and height (64 to 2048 pixels).</p><p><img src="'+s+'" alt="Canvas sizes"></p></li><li><p><strong>Choose frames per second</strong> — how many drawings play each second. <strong>12 fps</strong> is a good start. The bouncing ball shows how fast it will look.</p><p><img src="'+n+'" alt="Frames per second"></p></li><li><p>Tap <strong>Create project</strong>.</p></li></ol><blockquote><p><strong>Good to know:</strong> the canvas size cannot be changed after the project is created. The name, speed and background can be changed any time in <strong>Project settings</strong>.</p></blockquote><h2 id="work-with-your-projects" tabindex="-1">Work with your projects <a class="header-anchor" href="#work-with-your-projects" aria-label="Permalink to &quot;Work with your projects&quot;">​</a></h2><p><strong>Long-press</strong> a project to select it. Tap more cards to select several.</p><p><img src="'+i+'" alt="Selecting a project"></p><p>The bar at the bottom then lets you:</p><ul><li>✏️ <strong>Rename</strong> (one project at a time)</li><li>⧉ <strong>Duplicate</strong> — makes a copy called &quot;… copy&quot;</li><li><strong>Share / Export project</strong> — saves the whole project as a <code>.flippa</code> file you can send, back up or open on another phone</li><li>🗑 <strong>Delete</strong> — asks first, and cannot be undone</li></ul><p>Tap <strong>✕</strong> at the top to leave selection mode.</p><h3 id="sort-import-and-select" tabindex="-1">Sort, import and select <a class="header-anchor" href="#sort-import-and-select" aria-label="Permalink to &quot;Sort, import and select&quot;">​</a></h3><p>Tap <strong>⋮</strong> next to the tabs.</p><p><img src="'+p+'" alt="Sort and import menu"></p><ul><li><strong>Sort by</strong> — Last modified, Name or Date created.</li><li><strong>Import project</strong> — open a Toonik backup (<code>.flippa</code>) or a <strong>FlipaClip project (<code>.fc</code>)</strong>. It is added as a new project; nothing you already have is replaced. From FlipaClip, the layers and drawings come across (layer effects and sound do not).</li><li><strong>Select</strong> — start selection mode.</li></ul><h3 id="time-lapse-recording" tabindex="-1">Time-lapse recording <a class="header-anchor" href="#time-lapse-recording" aria-label="Permalink to &quot;Time-lapse recording&quot;">​</a></h3><p>Toonik can record every stroke you draw and turn it into a time-lapse video of your drawing. Select a project, tap <strong>⋯</strong> at the top, and switch on <strong>Time-Lapse Recording</strong>. Later, use <strong>Share Time-Lapse</strong> from the same place. Time-lapse videos also appear in the <strong>Movies</strong> tab.</p><p><img src="'+l+'" alt="Project options"></p><h2 id="your-work-is-saved-automatically" tabindex="-1">Your work is saved automatically <a class="header-anchor" href="#your-work-is-saved-automatically" aria-label="Permalink to &quot;Your work is saved automatically&quot;">​</a></h2><p>Toonik saves while you draw (every 10 seconds by default — you can change this in Settings) and again when you leave the editor or switch to another app. Your projects stay on your phone; nothing you draw is uploaded anywhere.</p><h2 id="what-s-new-and-notifications" tabindex="-1">What&#39;s new and notifications <a class="header-anchor" href="#what-s-new-and-notifications" aria-label="Permalink to &quot;What&#39;s new and notifications&quot;">​</a></h2><p><strong>What&#39;s new</strong> (side menu) lists every update and what it changed. The <strong>bell</strong> keeps the latest 15 messages from Toonik, even ones you missed. Tap a message to open its link.</p><p><img src="'+c+'" alt="What&#39;s new"></p><p><img src="'+g+'" alt="Notifications"></p>',33)])])}const S=d(w,[["render",f]]);export{q as __pageData,S as default};
